code.text:
#main  { color: green; }
.alert { color: red; }
p      { color: blue; }

div {
  background-color: #cce5ff;
  background: url("pattern.png") no-repeat center/cover;
}

div {
  width: 320px;
  padding: 30px;
  border: 5px solid gray;
  margin: 50px;
}

.box {
  box-sizing: content-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
}

.box {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
}

.container {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.container { display: flex; width: 600px; }
.item { flex-basis: 100px; }
.a { flex-grow: 1; }
.b { flex-grow: 2; }
.c { flex-grow: 0; }

.card  { position: relative; }
.badge { position: absolute;
         top: -8px; right: -8px; }

.a     { position: relative; z-index: 1; }
.popup { position: absolute; z-index: 9999; }
.b     { position: relative; z-index: 2; }

button {
  transition: background 0.5s;
}
button:hover {
  background: black;
  transform: scale(1.1);
}

.grid {
  display: grid;
  width: 640px;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.cards {
  display: grid;
  width: 1100px;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.page {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-areas:
    "header header"
    "nav    main"
    "footer footer";
}
